    return (remaining * (remaining * 10.0 - 100.0)) >= item * (remaining * 10.0 - 100.0)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    available = bins - item
    return -(available * (available - 1.0)) >= item * (available.item() - 1.0)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining_capacity = bins - item
    remaining_capacity[remaining_capacity < 0] = 0
    utilization = 1.0 - remaining_capacity / bins
    return (np.sin(np.pi * utilization) * np.log(utilization + 1e-8) + np.cos(np.pi * utilization)) * (remaining_capacity <= 0.5 * bins)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    available = bins - item
    available = np.maximum(available, 0)
    utilization = 1.0 - available / bins
    return np.log(utilization + 1e-8) * (available <= 0.5 * bins)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining_capacity = bins - item
    remaining_capacity[remaining_capacity < 0] = 0
    return 1.0 / (remaining_capacity + 1e-8)

