def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining_capacity = bins - item
    remaining_capacity[remaining_capacity < 0] = 0
    utilization = 1.0 - remaining_capacity / bins
    return (utilization ** 2) * np.log(utilization + 1e-8) * (remaining_capacity <= 0.5 * bins)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return -np.where(remaining > 0, remaining, np.inf)

